"C:\\windows\\system32\\windowspowershell\\v1.0\\powershell.exe" -Command 'Get-ChildItem -File .relay/runs | Select-Object Name,Length
$reviewSessionFiles = Get-ChildItem -LiteralPath '"'C:\\Users\\alileus\\.codex\\sessions\\2026\\09\\24' -Filter '*01a0d15b-4669-7b11-8032-7c3756228074*' -File -ErrorAction SilentlyContinue
foreach ("'$reviewSessionFile in $reviewSessionFiles) {
    $reviewSessionFile.FullName
    $reviewContexts = Get-Content -LiteralPath $reviewSessionFile.FullName | Select-String '"'\"type\":\"turn_context\"' | Select-Object -Last 1
    foreach ("'$reviewContext in $reviewContexts) {
        $reviewPayload = ($reviewContext.Line | ConvertFrom-Json).payload
        $reviewPayload | Select-Object turn_id,model,effort,sandbox_policy,approval_policy | ConvertTo-Json -Depth 5
    }
}'

